package com.vyron.assistant;

import android.Manifest;import android.app.*;import android.content.*;import android.content.pm.PackageManager;import android.graphics.*;import android.graphics.drawable.GradientDrawable;import android.net.Uri;import android.os.*;import android.provider.Settings;import android.speech.RecognizerIntent;import android.speech.tts.TextToSpeech;import android.view.*;import android.widget.*;import org.json.*;import java.io.*;import java.net.*;import java.nio.charset.StandardCharsets;import java.text.DateFormat;import java.util.*;import java.util.concurrent.*;

public class MainActivity extends Activity {
 private final ExecutorService io=Executors.newSingleThreadExecutor(); private android.content.SharedPreferences prefs; private TextView status,user,reply; private TextToSpeech tts; private boolean ttsReady=false; private String queued=""; private final int bg=Color.rgb(5,12,29), panel=Color.rgb(14,31,53), cyan=Color.rgb(63,220,255), white=Color.rgb(235,244,255), muted=Color.rgb(153,176,203);
 public void onCreate(Bundle b){super.onCreate(b);prefs=getSharedPreferences("vyron_settings",MODE_PRIVATE);getWindow().setStatusBarColor(bg);getWindow().setNavigationBarColor(bg);tts=new TextToSpeech(this,r->{ttsReady=r==TextToSpeech.SUCCESS;if(ttsReady&&!queued.isEmpty())say(queued);});ui();if(Build.VERSION.SDK_INT>=23&&checkSelfPermission(Manifest.permission.RECORD_AUDIO)!=PackageManager.PERMISSION_GRANTED)requestPermissions(new String[]{Manifest.permission.RECORD_AUDIO},3);if(Build.VERSION.SDK_INT>=33&&checkSelfPermission(Manifest.permission.POST_NOTIFICATIONS)!=PackageManager.PERMISSION_GRANTED)requestPermissions(new String[]{Manifest.permission.POST_NOTIFICATIONS},4);}
 int dp(int n){return (int)(n*getResources().getDisplayMetrics().density+.5f);} LinearLayout.LayoutParams full(){return new LinearLayout.LayoutParams(-1,-2);} GradientDrawable shape(int color,int stroke){GradientDrawable d=new GradientDrawable();d.setColor(color);d.setCornerRadius(dp(20));d.setStroke(dp(1),stroke);return d;}
 void ui(){ScrollView sc=new ScrollView(this);LinearLayout root=new LinearLayout(this);root.setOrientation(1);root.setGravity(Gravity.CENTER_HORIZONTAL);root.setPadding(dp(22),dp(25),dp(22),dp(24));root.setBackgroundColor(bg);sc.addView(root);TextView title=new TextView(this);title.setText("V Y R O N");title.setTextColor(cyan);title.setTextSize(32);title.setTypeface(null,1);title.setGravity(17);root.addView(title,full());TextView sub=new TextView(this);sub.setText("YOUR VOICE-FIRST AI COMPANION");sub.setTextColor(muted);sub.setTextSize(14);sub.setGravity(17);root.addView(sub,full());TextView orb=new TextView(this);orb.setText("V");orb.setTextColor(-1);orb.setTextSize(48);orb.setTypeface(null,1);orb.setGravity(17);GradientDrawable od=new GradientDrawable();od.setShape(1);od.setColor(Color.rgb(11,43,72));od.setStroke(dp(4),cyan);orb.setBackground(od);LinearLayout.LayoutParams op=new LinearLayout.LayoutParams(dp(166),dp(166));op.gravity=1;op.topMargin=dp(24);op.bottomMargin=dp(10);root.addView(orb,op);status=new TextView(this);status.setText("READY • TAP TO SPEAK");status.setTextColor(cyan);status.setGravity(17);status.setTextSize(14);root.addView(status,full());user=panel("You: Nothing yet. Tap Speak to Vyron.");reply=panel("VYRON: Ready. Add a Groq API key in Settings for AI answers. Local commands work without one.");addPanel(root,user);addPanel(root,reply);addButton(root,"🎙  SPEAK TO VYRON",v->listen());addButton(root,"⚙  AI & VOICE SETTINGS",v->settings());addButton(root,"FLOATING ORB",v->floating());addButton(root,"SCREEN INTERACTION SETUP",v->startActivity(new Intent(Settings.ACTION_ACCESSIBILITY_SETTINGS)));addButton(root,"NOTIFICATION READER SETUP",v->startActivity(new Intent("android.settings.ACTION_NOTIFICATION_LISTENER_SETTINGS")));addButton(root,"TRY: OPEN SPOTIFY",v->command("open spotify"));TextView note=new TextView(this);note.setText("VYRON v1.1 • Optional AI keys • Android permissions required for screen and notification features");note.setTextColor(muted);note.setGravity(17);note.setTextSize(12);LinearLayout.LayoutParams np=full();np.topMargin=dp(15);root.addView(note,np);setContentView(sc);}
 TextView panel(String s){TextView t=new TextView(this);t.setText(s);t.setTextColor(white);t.setTextSize(16);t.setPadding(dp(16),dp(15),dp(16),dp(15));t.setBackground(shape(panel,Color.rgb(44,92,125)));return t;}void addPanel(LinearLayout r,TextView t){LinearLayout.LayoutParams p=full();p.topMargin=dp(14);r.addView(t,p);}void addButton(LinearLayout r,String s,View.OnClickListener l){Button b=new Button(this);b.setText(s);b.setTextColor(white);b.setTextSize(14);b.setAllCaps(false);b.setBackground(shape(panel,Color.rgb(44,92,125)));b.setOnClickListener(l);LinearLayout.LayoutParams p=full();p.topMargin=dp(12);p.height=dp(60);r.addView(b,p);}
 void listen(){if(Build.VERSION.SDK_INT>=23&&checkSelfPermission(Manifest.permission.RECORD_AUDIO)!=PackageManager.PERMISSION_GRANTED){requestPermissions(new String[]{Manifest.permission.RECORD_AUDIO},3);return;}try{Intent i=new Intent(RecognizerIntent.ACTION_RECOGNIZE_SPEECH);i.putExtra(RecognizerIntent.EXTRA_LANGUAGE_MODEL,RecognizerIntent.LANGUAGE_MODEL_FREE_FORM);i.putExtra(RecognizerIntent.EXTRA_LANGUAGE,Locale.getDefault());i.putExtra(RecognizerIntent.EXTRA_PROMPT,"Speak to VYRON");startActivityForResult(i,11);}catch(Exception e){answer("Speech recognition is unavailable. Enable an Android speech recognition provider.");}}
 protected void onActivityResult(int req,int res,Intent data){super.onActivityResult(req,res,data);if(req==11&&res==RESULT_OK&&data!=null){ArrayList<String>a=data.getStringArrayListExtra(RecognizerIntent.EXTRA_RESULTS);if(a!=null&&!a.isEmpty()){user.setText("You: "+a.get(0));command(a.get(0));}}}
 void command(String raw){String q=raw.trim(),l=q.toLowerCase(Locale.ROOT);status.setText("WORKING…");if(l.contains("open spotify")||l.equals("spotify")||l.startsWith("spotify ")){String term=q.replaceFirst("(?i)^open\\s+spotify\\s*","").replaceFirst("(?i)^spotify\\s*","").trim();try{Intent a=getPackageManager().getLaunchIntentForPackage("com.spotify.music");if(a!=null)startActivity(a);else open("https://open.spotify.com/search/"+Uri.encode(term));}catch(Exception e){open("https://open.spotify.com/search/"+Uri.encode(term));}answer(term.isEmpty()?"Opening Spotify.":"Opening Spotify. Search for "+term+" there.");return;}if(l.contains("youtube")){String term=q.replaceFirst("(?i)^open\\s+youtube\\s*","").replaceFirst("(?i)^youtube\\s*","").replaceFirst("(?i)^search\\s*","").trim();open("https://www.youtube.com/results?search_query="+Uri.encode(term));answer(term.isEmpty()?"Opening YouTube.":"Searching YouTube for "+term+".");return;}if(l.startsWith("search google for ")||l.startsWith("google ")){String term=q.replaceFirst("(?i)^search google for\\s*","").replaceFirst("(?i)^google\\s*","");open("https://www.google.com/search?q="+Uri.encode(term));answer("Searching Google for "+term);return;}if(l.contains("what time")||l.equals("time")){answer("It is "+DateFormat.getTimeInstance(DateFormat.SHORT).format(new Date()));return;}if(l.contains("read notifications")||l.contains("my notifications")){String n=VyronNotificationListener.latestText;answer(n.isEmpty()?"No notification captured yet. Enable VYRON Notification Reader in Android settings first.":"Latest notification: "+n);return;}if(l.contains("scroll down")||l.equals("scroll")){answer(VyronAccessibilityService.scroll(true)?"Scrolling down.":"Enable VYRON Screen Interaction in Accessibility settings first.");return;}if(l.contains("scroll up")){answer(VyronAccessibilityService.scroll(false)?"Scrolling up.":"Enable VYRON Screen Interaction in Accessibility settings first.");return;}if(l.equals("back")||l.contains("go back")){answer(VyronAccessibilityService.back()?"Going back.":"Enable VYRON Screen Interaction in Accessibility settings first.");return;}if(l.startsWith("call ")){try{startActivity(new Intent(Intent.ACTION_DIAL,Uri.parse("tel:")));answer("Dialer opened. Select "+q.substring(5)+" and confirm the call.");}catch(Exception e){answer("Could not open dialer.");}return;}if(l.startsWith("message ")||l.startsWith("send whatsapp")){String msg=q.replaceFirst("(?i)^send whatsapp\\s*","").replaceFirst("(?i)^message\\s*","");open("https://wa.me/?text="+Uri.encode(msg));answer("WhatsApp link opened if available. Review the recipient and message before sending.");return;}askAi(q);}
 void open(String u){try{startActivity(new Intent(Intent.ACTION_VIEW,Uri.parse(u)));}catch(Exception e){Toast.makeText(this,"No app or browser can open that link",Toast.LENGTH_LONG).show();}}void answer(String s){reply.setText("VYRON: "+s);status.setText("READY");say(s);}void askAi(String q){String key=prefs.getString("groq"," ").trim();if(key.isEmpty()){answer("I heard you. Add your Groq API key in AI & Voice Settings to enable general AI answers. Local commands still work without it.");return;}status.setText("THINKING…");io.execute(()->{HttpURLConnection c=null;try{c=(HttpURLConnection)new URL("https://api.groq.com/openai/v1/chat/completions").openConnection();c.setRequestMethod("POST");c.setConnectTimeout(15000);c.setReadTimeout(30000);c.setDoOutput(true);c.setRequestProperty("Content-Type","application/json");c.setRequestProperty("Authorization","Bearer "+key);JSONObject b=new JSONObject();b.put("model","llama-3.3-70b-versatile");JSONArray m=new JSONArray();m.put(new JSONObject().put("role","system").put("content","You are VYRON, a friendly voice-first Android assistant. Answer naturally and concisely. Never claim you performed device actions unless the app confirms it. Reply in the user's language when possible."));m.put(new JSONObject().put("role","user").put("content",q));b.put("messages",m);try(OutputStream o=c.getOutputStream()){o.write(b.toString().getBytes(StandardCharsets.UTF_8));}int code=c.getResponseCode();InputStream in=code<300?c.getInputStream():c.getErrorStream();String body=read(in);if(code>=300)throw new Exception("API returned HTTP "+code+": "+body);String a=new JSONObject(body).getJSONArray("choices").getJSONObject(0).getJSONObject("message").getString("content").trim();runOnUiThread(()->answer(a));}catch(Exception e){runOnUiThread(()->answer("AI request failed. Check internet, Groq key, and model availability. "+e.getMessage()));}finally{if(c!=null)c.disconnect();}});}String read(InputStream i)throws Exception{StringBuilder s=new StringBuilder();try(BufferedReader r=new BufferedReader(new InputStreamReader(i,StandardCharsets.UTF_8))){String l;while((l=r.readLine())!=null)s.append(l);}return s.toString();}
 void say(String s){String key=prefs.getString("eleven"," ").trim(),voice=prefs.getString("voice","").trim();if(!key.isEmpty()&&!voice.isEmpty()){io.execute(()->{try{HttpURLConnection c=(HttpURLConnection)new URL("https://api.elevenlabs.io/v1/text-to-speech/"+voice).openConnection();c.setRequestMethod("POST");c.setConnectTimeout(15000);c.setReadTimeout(30000);c.setDoOutput(true);c.setRequestProperty("xi-api-key",key);c.setRequestProperty("Content-Type","application/json");c.setRequestProperty("Accept","audio/mpeg");JSONObject b=new JSONObject().put("text",s).put("model_id","eleven_multilingual_v2");try(OutputStream o=c.getOutputStream()){o.write(b.toString().getBytes(StandardCharsets.UTF_8));}if(c.getResponseCode()>=300)throw new Exception();File f=new File(getCacheDir(),"reply.mp3");try(InputStream in=c.getInputStream();FileOutputStream out=new FileOutputStream(f)){byte[]buf=new byte[8192];int n;while((n=in.read(buf))>0)out.write(buf,0,n);}c.disconnect();runOnUiThread(()->{try{android.media.MediaPlayer p=new android.media.MediaPlayer();p.setDataSource(f.getAbsolutePath());p.setOnCompletionListener(android.media.MediaPlayer::release);p.prepare();p.start();}catch(Exception e){fallbackSpeak(s);}});return;}catch(Exception ignored){}runOnUiThread(()->fallbackSpeak(s));});}else fallbackSpeak(s);}void fallbackSpeak(String s){if(!ttsReady){queued=s;return;}tts.setLanguage(Locale.getDefault());tts.speak(s,TextToSpeech.QUEUE_FLUSH,null,"vyron");}
 void settings(){LinearLayout box=new LinearLayout(this);box.setOrientation(1);box.setPadding(dp(18),dp(6),dp(18),dp(4));EditText g=new EditText(this);g.setSingleLine(true);g.setHint("Groq API key (AI answers)");g.setText(prefs.getString("groq",""));box.addView(g);EditText e=new EditText(this);e.setSingleLine(true);e.setHint("ElevenLabs API key (optional)");e.setText(prefs.getString("eleven",""));box.addView(e);EditText v=new EditText(this);v.setSingleLine(true);v.setHint("ElevenLabs Voice ID (optional)");v.setText(prefs.getString("voice",""));box.addView(v);TextView info=new TextView(this);info.setText("Keys are stored in private app preferences, not encrypted by this starter. Never commit keys to GitHub. Provider limits or charges may apply.");info.setTextSize(12);box.addView(info);new AlertDialog.Builder(this).setTitle("VYRON Settings").setView(box).setNegativeButton("Cancel",(d,w)->{}).setPositiveButton("Save",(d,w)->{prefs.edit().putString("groq",g.getText().toString().trim()).putString("eleven",e.getText().toString().trim()).putString("voice",v.getText().toString().trim()).apply();Toast.makeText(this,"Settings saved",Toast.LENGTH_SHORT).show();}).show();}
 void floating(){if(!Settings.canDrawOverlays(this)){startActivity(new Intent(Settings.ACTION_MANAGE_OVERLAY_PERMISSION,Uri.parse("package:"+getPackageName())));Toast.makeText(this,"Allow display over other apps, then tap Floating Orb again",Toast.LENGTH_LONG).show();return;}try{startService(new Intent(this,FloatingOrbService.class));}catch(Exception e){Toast.makeText(this,"Could not start orb: "+e.getMessage(),Toast.LENGTH_LONG).show();}}
 protected void onDestroy(){if(tts!=null){tts.stop();tts.shutdown();}io.shutdown();super.onDestroy();}
}
